WITH valid AS (SELECT *, UPPER(TRIM(product_name)) product_name_normalized FROM products WHERE launch_date >= TO_DATE('2023-09-13')) SELECT id, product_name, category, cost, stock_qty, launch_date, supplier_id, product_name_normalized, AVG(price) OVER (ORDER BY launch_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) price_avg_5_prior, MIN(price) OVER (PARTITION BY category) category_min_price, LAG(cost, 1) OVER (PARTITION BY category, brand ORDER BY cost, id) prev_cost FROM valid
